// One gateway invocation lifecycle event -> the Plane ticket it is about and
// what to do with its agent:working chip. The triggers' data filter already
// dropped every turn no ticket command launched (Claude/Codex sessions etc.),
// and everything needed rides on data.context: no static data, no board map.
// Boards Krebs owns (managed/shadow execution) are listed in the n8n env var
// KREBS_FENCED_BOARDS (JSON array of board ids); Krebs keeps its own chips.
let fenced = [];
try {
  const raw = $env.KREBS_FENCED_BOARDS;
  fenced = raw ? JSON.parse(raw) : [];
} catch (error) {
  fenced = [];
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const env = items[i].json || {};
  const data = env.data || {};
  const ctx = data.context || {};
  if (!ctx.workspace || !ctx.board_id || !ctx.ticket_id) continue;
  if (Array.isArray(fenced) && fenced.includes(ctx.board_id)) continue;
  const type = String(env.type || '');
  out.push({
    json: {
      action: type.endsWith('.started') ? 'add' : 'remove',
      ws: ctx.workspace,
      board: ctx.board_id,
      ticketId: ctx.ticket_id,
      ticketKey: ctx.ticket_key ?? null,
      reason: ctx.reason ?? null,
      agentId: data.target_agent_id ?? null,
      eventType: type,
      eventId: env.id ?? null,
      correlationid: env.correlationid ?? null,
      // Set only by Stale Chip Sweep. Chip — Plan Write needs both to leave a
      // ticket alone that changed after this turn ended.
      sweep: env.sweep === true,
      eventTime: env.time ?? null,
    },
    pairedItem: { item: i },
  });
}
return out;

// Resolve the chip label BY NAME on this board. A board without one
// (CANDY/CANDYS carry a soft-deleted row Plane will not recreate) simply gets
// no chip: skip quietly, never fail the lane.
const LABEL = 'agent:working';
// The Plane HTTP nodes run with On Error = Continue, so a failed request
// arrives here as { error } instead of failing the execution. 404/410 means
// the ticket (or its board) was deleted while the agent's turn was running:
// there is no chip left to set, so the item is skipped and the execution stays
// green. Any other failure (auth, 5xx) still fails it, with the ticket named.
const GONE = [404, 410];
function httpStatus(err) {
  if (err && typeof err === 'object') {
    const candidates = [err.httpCode, err.statusCode, err.status, err.response && err.response.status, err.cause && err.cause.status];
    for (const v of candidates) {
      const n = Number(v);
      if (Number.isInteger(n) && n >= 100 && n < 600) return n;
    }
  }
  const text = err && typeof err === 'object' ? `${err.message || ''} ${err.description || ''}` : String(err || '');
  const m = text.match(/\b([1-5]\d\d)\b/);
  return m ? Number(m[1]) : null;
}
function failure(step, t, err) {
  const status = httpStatus(err);
  if (GONE.includes(status)) return null;
  const detail = err && typeof err === 'object' ? err.message || err.description || JSON.stringify(err) : String(err);
  return new Error(`${step} failed for ${t.ticketKey || t.ticketId} (board ${t.board}): HTTP ${status ?? '?'} ${String(detail).slice(0, 200)}`);
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const target = $('Chip — Target').itemMatching(i).json;
  const body = items[i].json || {};
  if (body.error) {
    const err = failure('Chip — List Labels', target, body.error);
    if (err) throw err;
    continue;
  }
  const labels = Array.isArray(body.results) ? body.results : [];
  const hit = labels.find((l) => l && typeof l.name === 'string' && l.name.trim().toLowerCase() === LABEL);
  if (!hit) continue;
  out.push({ json: { ...target, labelId: hit.id }, pairedItem: { item: i } });
}
return out;

// Read-modify-write of the ticket's label set. No-op writes are dropped: the
// chip is already on (add) or already gone (remove), or a sweep remove found
// the ticket changed after the turn ended (see touchedSinceTurn). A ticket that was deleted
// mid-turn (404/410, or a soft-deleted row) is skipped, not written.
// The Plane HTTP nodes run with On Error = Continue, so a failed request
// arrives here as { error } instead of failing the execution. 404/410 means
// the ticket (or its board) was deleted while the agent's turn was running:
// there is no chip left to set, so the item is skipped and the execution stays
// green. Any other failure (auth, 5xx) still fails it, with the ticket named.
const GONE = [404, 410];
// agent:working has two writers: this lane, and pilot's `px claim` (which adds
// it) / `px close` (which removes it). The label cannot say who put it there.
// A sweep remove (Stale Chip Sweep, up to 48h after the turn) therefore only
// takes off a chip nobody has touched since the turn ended: if the ticket's
// updated_at is later than the ending event's time, a worker's px claim, a
// new turn's own chip or anyone's edit happened since, and the ticket is left
// as it is. Unknown times also leave it: when in doubt, the chip stays. The
// slack is small on purpose: the gateway and Plane share this host's clock,
// every write of the turn itself lands before its ending event, and a claim
// made seconds after the turn is exactly what must survive. (This lane's own
// live remove lands ~0.5s after the end, but when it lands the chip is gone.)
// The live lane (sweep false) removes at the real turn end.
const SWEEP_SLACK_MS = 5 * 1000;
function touchedSinceTurn(t, issue) {
  const ended = Date.parse(t.eventTime);
  const updated = Date.parse(issue.updated_at);
  if (Number.isNaN(ended) || Number.isNaN(updated)) return true;
  return updated > ended + SWEEP_SLACK_MS;
}
function httpStatus(err) {
  if (err && typeof err === 'object') {
    const candidates = [err.httpCode, err.statusCode, err.status, err.response && err.response.status, err.cause && err.cause.status];
    for (const v of candidates) {
      const n = Number(v);
      if (Number.isInteger(n) && n >= 100 && n < 600) return n;
    }
  }
  const text = err && typeof err === 'object' ? `${err.message || ''} ${err.description || ''}` : String(err || '');
  const m = text.match(/\b([1-5]\d\d)\b/);
  return m ? Number(m[1]) : null;
}
function failure(step, t, err) {
  const status = httpStatus(err);
  if (GONE.includes(status)) return null;
  const detail = err && typeof err === 'object' ? err.message || err.description || JSON.stringify(err) : String(err);
  return new Error(`${step} failed for ${t.ticketKey || t.ticketId} (board ${t.board}): HTTP ${status ?? '?'} ${String(detail).slice(0, 200)}`);
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const t = $('Chip — Resolve Label').itemMatching(i).json;
  const issue = items[i].json || {};
  if (issue.error) {
    const err = failure('Chip — Read Issue', t, issue.error);
    if (err) throw err;
    continue;
  }
  if (issue.deleted_at) continue;
  const current = (issue.labels || [])
    .map((l) => (l && typeof l === 'object' ? l.id : l))
    .filter(Boolean);
  const has = current.includes(t.labelId);
  if (t.action === 'add' ? has : !has) continue;
  if (t.sweep && t.action === 'remove' && touchedSinceTurn(t, issue)) continue;
  const labels = t.action === 'add' ? [...current, t.labelId] : current.filter((id) => id !== t.labelId);
  out.push({ json: { ...t, labels }, pairedItem: { item: i } });
}
return out;

// The ticket can also vanish between the read and the write. Write Labels runs
// with On Error = Continue so that race lands here: 404/410 is the same no-op
// as a ticket already gone; anything else fails the execution, ticket named.
// The Plane HTTP nodes run with On Error = Continue, so a failed request
// arrives here as { error } instead of failing the execution. 404/410 means
// the ticket (or its board) was deleted while the agent's turn was running:
// there is no chip left to set, so the item is skipped and the execution stays
// green. Any other failure (auth, 5xx) still fails it, with the ticket named.
const GONE = [404, 410];
function httpStatus(err) {
  if (err && typeof err === 'object') {
    const candidates = [err.httpCode, err.statusCode, err.status, err.response && err.response.status, err.cause && err.cause.status];
    for (const v of candidates) {
      const n = Number(v);
      if (Number.isInteger(n) && n >= 100 && n < 600) return n;
    }
  }
  const text = err && typeof err === 'object' ? `${err.message || ''} ${err.description || ''}` : String(err || '');
  const m = text.match(/\b([1-5]\d\d)\b/);
  return m ? Number(m[1]) : null;
}
function failure(step, t, err) {
  const status = httpStatus(err);
  if (GONE.includes(status)) return null;
  const detail = err && typeof err === 'object' ? err.message || err.description || JSON.stringify(err) : String(err);
  return new Error(`${step} failed for ${t.ticketKey || t.ticketId} (board ${t.board}): HTTP ${status ?? '?'} ${String(detail).slice(0, 200)}`);
}
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const body = items[i].json || {};
  if (!body.error) continue;
  const err = failure('Chip — Write Labels', $('Chip — Plan Write').itemMatching(i).json, body.error);
  if (err) throw err;
}
return [];

// Stale-chip safety net. The Invocation Lifecycle trigger is a durable
// JetStream consumer that handles started/completed/failed one at a time in
// stream order, so the live lane should never leave a chip behind. This hourly
// sweep covers what that lane cannot: a chip write that failed (Plane 5xx), an
// n8n outage longer than the trigger's catch-up window, or an expired durable.
//
// Input: the hermes gateway's invocation events of the last 48h from
// Candystore. For every ticket whose LATEST gateway invocation event is a
// completed/failed one at least SETTLE_MS old, emit that event into
// Chip — Target as a 'remove' marked sweep. The chip lane then reads the
// ticket and only writes when agent:working is still there AND the ticket has
// not changed since that turn ended: agent:working is also pilot's claim
// marker, so a ticket a worker `px claim`ed after the turn keeps it (Chip —
// Plan Write, touchedSinceTurn). A clean ticket costs two GETs and no write. A ticket whose latest event is a start (a turn is
// running, or its end has not reached Candystore yet) is left alone.
const SETTLE_MS = 10 * 60 * 1000;
const REASONS = ['ticket-grooming', 'ticket-delegation'];
const first = $input.all()[0];
const body = (first && first.json) || {};
const rows = Array.isArray(body.events) ? body.events : [];
const latest = new Map();
for (const row of rows) {
  const data = (row && row.data) || {};
  const ctx = data.context || {};
  if (!REASONS.includes(ctx.reason)) continue;
  if (!ctx.ticket_id || !ctx.board_id || !ctx.workspace) continue;
  const at = Date.parse(row.time);
  if (Number.isNaN(at)) continue;
  const key = `${ctx.board_id}:${ctx.ticket_id}`;
  const previous = latest.get(key);
  // Ties go to the start: when in doubt, leave the chip on.
  if (!previous || at > previous.at || (at === previous.at && /\.started$/.test(String(row.type)))) {
    latest.set(key, { at, row });
  }
}
const now = Date.now();
const out = [];
for (const { at, row } of latest.values()) {
  if (!/\.(completed|failed)$/.test(String(row.type))) continue;
  if (now - at < SETTLE_MS) continue;
  out.push({
    json: {
      specversion: '1.0',
      id: row.id,
      type: row.type,
      time: row.time,
      kind: 'event',
      correlationid: row.correlationid ?? null,
      data: { target_agent_id: (row.data || {}).target_agent_id ?? null, context: row.data.context },
      sweep: true,
    },
    pairedItem: { item: 0 },
  });
}
return out;
